const parsed = $('Code - Procesar IA').first().json;
const chatId = String(parsed.chat_id || '').trim();
let ids = [];
try {
  ids = JSON.parse(parsed.propiedades_mostrar || '[]');
} catch (e) {
  ids = [];
}
if (!Array.isArray(ids)) ids = [];

function formatPrecio(precio, precioUsd) {
  if (precioUsd) {
    return 'USD ' + precioUsd.toLocaleString('es-AR');
  }
  return String(precio || '').trim();
}

function cardCaption(m, id) {
  const titulo = m.titulo || m.caption || id;
  const tipo = m.tipo || 'Propiedad';
  const op = m.operacion || 'Venta';
  const zona = m.zona ? String(m.zona).trim() : '';
  const precio = formatPrecio(m.precio, m.precioUsd);
  const desc = String(m.descripcion || '').trim();
  const link = m.linkFicha || '';
  let cap =
    '🏠 *' +
    titulo +
    '*\n\n' +
    '🏠 Tipo: ' +
    tipo;
  if (zona) cap += '\n📍 ' + zona;
  cap += '\n🏷️ ' + op + '\n💰 Precio: ' + precio;
  if (desc) cap += '\n\n' + desc;
  if (link) cap += '\n\n🔗 Ver ficha: ' + link;
  return cap.slice(0, 1000);
}

const out = [];
for (const rawId of ids.slice(0, 3)) {
  const id = String(rawId || '').trim();
  const m = PROP_MEDIA[id];
  if (!m || !Array.isArray(m.fotos) || !m.fotos.length) continue;
  const fotos = m.fotos.slice(0, 4);
  out.push({
    json: {
      chat_id: chatId,
      photo_url: fotos[0],
      caption: cardCaption(m, id),
      propiedad_id: id,
    },
  });
  for (let i = 1; i < fotos.length; i++) {
    out.push({
      json: {
        chat_id: chatId,
        photo_url: fotos[i],
        caption: '',
        propiedad_id: id,
      },
    });
  }
}

if (!out.length) {
  return [{ json: { skip: true } }];
}
out[out.length - 1].json.is_last_photo = true;
return out;

/**
 * Prepara una fila para la hoja `Conversaciones_Revision` (revisión humana).
 *
 * Entradas esperadas desde el workflow:
 * - `repeticion_detectada` (boolean)
 * - `lead_completo` (WA: 'si'/'no' | TG: boolean)
 * - turnos: WA usa `consultas_count` como proxy, TG usa `turno`
 * - `historial_json` (string JSON)
 * - `mensajes_extra` (string JSON de mensajes adicionales, si existe)
 * - último mensaje + respuesta:
 *   - WA: `mensaje` + `respuesta_wa`
 *   - TG: `texto_usuario` + `respuesta_bot`
 */

const CANAL = 'whatsapp';
const UMBRAL_TURNOS_SIN_CLASIFICAR = 6;

function leadCompletoToBool(v) {
  if (typeof v === 'boolean') return v;
  const s = String(v || '').trim().toLowerCase();
  if (!s) return false;
  return s === 'si' || s === 'true' || s === 'calificado' || s === '1';
}

const repeticionDetectada = Boolean($json.repeticion_detectada);
const rateLimit = Boolean($json.rate_limit);
const leadCompleto = leadCompletoToBool($json.lead_completo);

// Proxy determinístico de "turnos" sin tocar el clasificador/IA
const turnos = Number($json.turno || $json.consultas_count || 0) || 0;
const sinClasificar = !leadCompleto && turnos >= UMBRAL_TURNOS_SIN_CLASIFICAR;

let motivo = '';
if (rateLimit) motivo = 'rate_limit';
else if (repeticionDetectada) motivo = 'REPETICION';
else if (sinClasificar) motivo = 'SIN_CLASIFICAR';

const registrar_revision = Boolean(motivo);
const fecha_hora = new Date().toISOString();

const chat_id = String($json.chat_id || '').trim();
const lead_name = String($json.lead_name || $json.nombre_usuario || '').trim();
const ultimo_mensaje_cliente = String($json.texto_usuario || $json.mensaje || '').trim();
const respuesta_bot = String($json.respuesta_bot || $json.respuesta_wa || '').trim();

return [
  {
    json: {
      registrar_revision,
      motivo,
      fecha_hora,
      canal: CANAL,
      chat_id,
      lead_name,
      ultimo_mensaje_cliente,
      respuesta_bot,
      historial_json: String($json.historial_json || '[]'),
      mensajes_extra: String($json.mensajes_extra || '[]'),
    },
  },
];

/**
 * SIMPLE-02 — Transcribe audio/voz WhatsApp con Groq Whisper.
 * Tokens se sustituyen en --deploy (__SET_*__).
 */
const META_TOKEN = '__SET_META_ACCESS_TOKEN__';
const GRAPH = '__SET_META_GRAPH_VERSION__';
const GROQ_KEY = '__SET_GROQ_API_KEY__';

const item = $input.first().json;
const mediaId = String(item.audio_media_id || '').trim();

if (!mediaId || String(item.mensaje || '').trim()) {
  return [{ json: { ...item, es_audio_sin_transcripcion: false } }];
}

function buildMultipart(buffer, filename, mime) {
  const boundary = '----NodoAudio' + Date.now();
  const headFile =
    '--' +
    boundary +
    '\r\nContent-Disposition: form-data; name="file"; filename="' +
    filename +
    '"\r\nContent-Type: ' +
    mime +
    '\r\n\r\n';
  const fields =
    '--' +
    boundary +
    '\r\nContent-Disposition: form-data; name="model"\r\n\r\nwhisper-large-v3-turbo\r\n' +
    '--' +
    boundary +
    '\r\nContent-Disposition: form-data; name="language"\r\n\r\nes\r\n';
  const end = '\r\n--' + boundary + '--\r\n';
  const body = Buffer.concat([
    Buffer.from(fields, 'utf8'),
    Buffer.from(headFile, 'utf8'),
    Buffer.from(buffer),
    Buffer.from(end, 'utf8'),
  ]);
  return { body, boundary };
}

async function transcribir() {
  if (!META_TOKEN || META_TOKEN.includes('SET_META') || !GROQ_KEY || GROQ_KEY.includes('SET_GROQ')) {
    return {
      ...item,
      mensaje: '',
      es_audio_sin_transcripcion: true,
      audio_error: 'faltan_credenciales',
    };
  }

  const meta = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://graph.facebook.com/' + GRAPH + '/' + encodeURIComponent(mediaId),
    headers: { Authorization: 'Bearer ' + META_TOKEN },
    json: true,
  });
  const fileUrl = String((meta && meta.url) || '').trim();
  if (!fileUrl) {
    return { ...item, mensaje: '', es_audio_sin_transcripcion: true, audio_error: 'sin_url' };
  }

  const bin = await this.helpers.httpRequest({
    method: 'GET',
    url: fileUrl,
    headers: { Authorization: 'Bearer ' + META_TOKEN },
    encoding: 'arraybuffer',
    returnFullResponse: false,
  });
  const buffer = Buffer.isBuffer(bin) ? bin : Buffer.from(bin);
  if (!buffer.length) {
    return { ...item, mensaje: '', es_audio_sin_transcripcion: true, audio_error: 'audio_vacio' };
  }

  const mime = String(item.audio_mime || (meta && meta.mime_type) || 'audio/ogg');
  const ext = /mpeg|mp3/i.test(mime) ? 'mp3' : /mp4|m4a/i.test(mime) ? 'm4a' : 'ogg';
  const { body, boundary } = buildMultipart(buffer, 'nota-voz.' + ext, mime);
  const whisper = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.groq.com/openai/v1/audio/transcriptions',
    headers: {
      Authorization: 'Bearer ' + GROQ_KEY,
      'Content-Type': 'multipart/form-data; boundary=' + boundary,
    },
    body,
    json: true,
  });
  const texto = String((whisper && (whisper.text || whisper.transcript)) || '').trim();
  if (!texto) {
    return { ...item, mensaje: '', es_audio_sin_transcripcion: true, audio_error: 'sin_texto' };
  }
  return {
    ...item,
    mensaje: texto,
    es_audio: true,
    es_audio_transcrito: true,
    es_audio_sin_transcripcion: false,
    audio_transcripto: texto,
  };
}

try {
  const out = await transcribir.call(this);
  return [{ json: out }];
} catch (e) {
  return [
    {
      json: {
        ...item,
        mensaje: '',
        es_audio_sin_transcripcion: true,
        audio_error: String((e && e.message) || e || 'transcribe_fail').slice(0, 180),
      },
    },
  ];
}
